const payload = $input.first().json.body || $input.first().json;

const companyName = 'Dhanam Holdings';
const voucherType = (payload.voucherType || 'Receipt').trim();
const partyName = (payload.partyName || 'Site Client / Contractor').trim();
const amount = parseFloat(payload.amount || 0);
const siteName = (payload.siteName || 'General Project').trim();
const payerType = (payload.payerType || 'Owner').trim(); // Owner, Contractor, Self
const isReceived = payload.isReceived !== undefined ? Boolean(payload.isReceived) : true;
const notes = payload.notes || payload.narration || `${siteName} site expense / billing`;
const recipientJid = payload.replyJid || payload.remoteJid || '919361599097@s.whatsapp.net';

// Format date for Tally (YYYYMMDD) - Educational mode accepts 01, 02, 31
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
let day = String(now.getDate()).padStart(2, '0');
if (!['01', '02', '31'].includes(day)) {
  day = '01'; // Fallback to 1st of month for Educational Mode compatibility
}
const tallyDate = `${year}${month}${day}`;
const displayDate = `${day}-${month}-${year}`;

// Build XML for Tally Prime Voucher
let xmlEnvelope = '';
if (voucherType === 'Receipt') {
  xmlEnvelope = `<ENVELOPE>
  <HEADER><VERSION>1</VERSION><TALLYREQUEST>Import</TALLYREQUEST><TYPE>Data</TYPE><ID>Vouchers</ID></HEADER>
  <BODY>
    <DESC><STATICVARIABLES><SVCURRENTCOMPANY>${companyName}</SVCURRENTCOMPANY></STATICVARIABLES></DESC>
    <DATA>
      <TALLYMESSAGE xmlns:UDF="TallyUDF">
        <VOUCHER VCHTYPE="Receipt" ACTION="Create">
          <DATE>${tallyDate}</DATE>
          <VOUCHERTYPENAME>Receipt</VOUCHERTYPENAME>
          <PARTYLEDGERNAME>${partyName}</PARTYLEDGERNAME>
          <NARRATION>${siteName} - ${notes} [Payer: ${payerType}]</NARRATION>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>${partyName}</LEDGERNAME>
            <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
            <AMOUNT>${amount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>Cash</LEDGERNAME>
            <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
            <AMOUNT>-${amount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
        </VOUCHER>
      </TALLYMESSAGE>
    </DATA>
  </BODY>
</ENVELOPE>`;
} else {
  // Payment Voucher
  xmlEnvelope = `<ENVELOPE>
  <HEADER><VERSION>1</VERSION><TALLYREQUEST>Import</TALLYREQUEST><TYPE>Data</TYPE><ID>Vouchers</ID></HEADER>
  <BODY>
    <DESC><STATICVARIABLES><SVCURRENTCOMPANY>${companyName}</SVCURRENTCOMPANY></STATICVARIABLES></DESC>
    <DATA>
      <TALLYMESSAGE xmlns:UDF="TallyUDF">
        <VOUCHER VCHTYPE="Payment" ACTION="Create">
          <DATE>${tallyDate}</DATE>
          <VOUCHERTYPENAME>Payment</VOUCHERTYPENAME>
          <PARTYLEDGERNAME>${partyName}</PARTYLEDGERNAME>
          <NARRATION>${siteName} - ${notes} [Paid for: ${payerType}]</NARRATION>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>${partyName}</LEDGERNAME>
            <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
            <AMOUNT>-${amount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>Cash</LEDGERNAME>
            <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
            <AMOUNT>${amount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
        </VOUCHER>
      </TALLYMESSAGE>
    </DATA>
  </BODY>
</ENVELOPE>`;
}

// Tamil WhatsApp Confirmation
const confirmationText = `🏢 *${companyName} - Tally வவுச்சர் பதிவு செய்யப்பட்டது!*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📄 *வவுச்சர் வகை:* ${voucherType}\n` +
  `📍 *சைட்:* ${siteName}\n` +
  `👤 *பார்ட்டி:* ${partyName}\n` +
  `💰 *தொகை:* ₹${amount.toLocaleString('en-IN')}\n` +
  `🏷️ *செலுத்தியவர்:* ${payerType} (${isReceived ? 'காசு பெறப்பட்டது ✅' : 'நிலுவையில் உள்ளது ⏳'})\n` +
  `📅 *தேதி:* ${displayDate}\n` +
  `📝 *குறிப்பு:* ${notes}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `_Tally Prime & Google Sheet-ல் உடனடியாகப் பதிவானது._`;

return [{
  json: {
    companyName,
    voucherType,
    partyName,
    amount,
    siteName,
    payerType,
    isReceived,
    notes,
    recipientJid,
    tallyDate,
    displayDate,
    xmlEnvelope,
    confirmationText
  }
}];
